item.command:
/bin/bash -lc "cat > index.html <<'EOF'
<"'!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#f5f6f1">
  <meta name="description" content="Plan your home clean in four simple steps.">
  <title>Book a clean · neat</title>
  <style>
    :root {
      --canvas: #f5f6f1; --surface: #fff; --ink: #253b31; --muted: #667168;
      --green: #315c45; --green-hover: #244734; --sage: #eaf0e5; --sage-strong: #d7e5cc;
      --line: #dfe4dc; --input-line: #939e92; --placeholder: #727b72;
      --danger: #a33130; --danger-bg: #fff5f3; --focus: #467150;
      --radius: 12px; --ease: 180ms ease; --body: '"'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      --display: 'Lora', Georgia, 'Times New Roman', serif;
    }
    * { box-sizing: border-box; }
    html { color-scheme: light; -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }
    body { margin: 0; background: var(--canvas); color: var(--ink); font: 15px/1.5 var(--body); }
    button, input, textarea { font: inherit; }
    button, input, textarea, a { -webkit-tap-highlight-color: transparent; }
    button { cursor: pointer; touch-action: manipulation; }
    button:disabled { cursor: default; }
    button { color: inherit; }
    a { color: inherit; }
    ::selection { background: var(--sage-strong); color: var(--ink); }
    :focus-visible { outline: 3px solid var(--focus); outline-offset: 4px; }
    [hidden] { display: none "'!important; }
    .icon { width: 20px; height: 20px; flex-shrink: 0; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
    .site-header { max-width: 1200px; margin: auto; height: 104px; padding: 0 40px; display: flex; align-items: center; justify-content: space-between; }
    .wordmark { display: inline-flex; gap: 10px; align-items: center; font-size: 32px; font-weight: 600; letter-spacing: -1.7px; text-decoration: none; }
    .brand-mark { width: 31px; height: 36px; }
    .header-note { display: flex; align-items: center; gap: 8px; color: var(--muted); font-size: 13px; }
    .header-note .icon { width: 16px; height: 16px; }
    main { max-width: 840px; padding: 28px 24px 56px; margin: auto; }
    .intro { text-align: center; margin-bottom: 40px; }
    h1 { font: 400 48px/1.18 var(--display); letter-spacing: -1.8px; margin: 0 0 16px; text-wrap: balance; }
    .intro p { color: var(--muted); margin: 0; font-size: 15px; }
    .progress { list-style: none; padding: 0; margin: 0 16px 32px; display: grid; grid-template-columns: repeat(4, 1fr); }
    .progress li { position: relative; text-align: center; }
    .progress li:not(:last-child)::after { position: absolute; content: '"''; height: 1px; background: var(--line); top: 20px; left: calc(50% + 28px); right: calc(-50% + 28px); }
    .progress li.completed::after { background: var(--green); }
    .step-button { border: 0; padding: 0 8px; background: transparent; display: inline-flex; flex-direction: column; align-items: center; gap: 10px; min-width: 80px; min-height: 70px; border-radius: 4px; }
    .step-number { width: 40px; height: 40px; display: grid; place-items: center; border: 1px solid #aab4a7; border-radius: 50%; background: var(--canvas); font-size: 13px; font-weight: 500; color: var(--muted); transition: background var(--ease); }
    .step-name { color: var(--muted); font-size: 13px; }
    .current .step-number { border-color: var(--green); background: var(--green); color: white; box-shadow: 0 0 0 5px var(--sage); }
    .current .step-name { color: var(--ink); font-weight: 600; }
    .completed .step-number { background: var(--sage); border-color: var(--green); color: var(--green); }
    .completed .step-name { color: var(--green); }
    .step-number .icon { width: 18px; height: 18px; }
    .booking-card { background: var(--surface); border: 1px solid var(--line); border-radius: 20px; box-shadow: 0 8px 32px #253b3105; overflow: hidden; }
    .card-content { padding: 36px 40px 40px; }
    .section-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; margin-bottom: 28px; }
    .section-icon { width: 44px; height: 44px; border-radius: var(--radius); background: var(--sage); display: grid; place-items: center; color: var(--green); margin-bottom: 20px; }
    .section-icon .icon { width: 23px; height: 23px; }
    h2 { font: 400 28px/1.25 var(--display); margin: 0 0 8px; letter-spacing: -.6px; text-wrap: balance; }
    .description { margin: 0; color: var(--muted); font-size: 14px; }
    .step-count { color: var(--muted); font-size: 12px; white-space: nowrap; margin-top: 6px; }
    .fields { display: grid; grid-template-columns: 1fr 1fr; gap: 24px 20px; }
    .field { min-width: 0; }
    .full { grid-column: 1 / -1; }
    label, legend { display: block; font-size: 13px; font-weight: 500; margin-bottom: 8px; }
    .optional { color: var(--muted); font-weight: 400; }
    input:not([type='radio']), textarea { display: block; width: 100%; height: 52px; border: 1px solid var(--input-line); border-radius: 8px; background: var(--surface); color: var(--ink); padding: 12px 16px; outline-offset: 2px; transition: border-color var(--ease), box-shadow var(--ease); caret-color: var(--green); }
    input::placeholder, textarea::placeholder { color: var(--placeholder); opacity: 1; }
    input:not([type='radio']):focus, textarea:focus { border-color: var(--green); box-shadow: 0 0 0 3px var(--sage); outline: 2px solid var(--green); outline-offset: 1px; }
    input[aria-invalid='true'] { border-color: var(--danger); background: var(--danger-bg); }
    .field-error { color: var(--danger); font-size: 12px; margin: 6px 0 0; }
    .field-error:empty { display: none; }
    .hint { font-size: 12px; color: var(--muted); margin: 12px 0 0; }
    .card-footer { border-top: 1px solid var(--line); padding: 24px 40px; display: flex; align-items: center; justify-content: space-between; gap: 16px; background: #fdfefb; }
    .next-note { font-size: 12px; color: var(--muted); }
    .next-note strong { font-weight: 500; color: var(--ink); }
    .primary, .secondary { display: inline-flex; align-items: center; justify-content: center; gap: 12px; min-height: 48px; padding: 12px 24px; border-radius: 8px; border: 1px solid transparent; font-size: 14px; font-weight: 500; transition: background var(--ease), border-color var(--ease); }
    .primary { color: white; background: var(--green); }
    .primary .icon { width: 18px; height: 18px; }
    .secondary { color: var(--muted); background: transparent; padding-left: 0; }
    .secondary .icon { width: 16px; height: 16px; }
    .primary:active { background: #193c2a; }
    .secondary:active { color: var(--ink); }
    .page-footer { display: flex; justify-content: center; align-items: center; gap: 8px; margin: 24px 0 0; color: var(--muted); font-size: 12px; }
    .page-footer .icon { width: 14px; height: 14px; }
    fieldset { border: 0; padding: 0; margin: 0; min-width: 0; }
    .home-fields { display: grid; gap: 28px; }
    .counter-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
    .counter-label { font-size: 14px; font-weight: 500; display: flex; align-items: center; gap: 12px; }
    .counter-label .icon { color: var(--muted); }
    .counter { display: flex; align-items: center; border: 1px solid var(--input-line); border-radius: 8px; overflow: hidden; }
    .counter button { border: none; width: 44px; height: 44px; background: var(--surface); display: grid; place-items: center; }
    .counter button:disabled { color: #aeb6ad; background: #fafbf8; }
    .counter button .icon { width: 16px; height: 16px; }
    .counter output { min-width: 40px; text-align: center; font-size: 14px; font-variant-numeric: tabular-nums; }
    .divider { border: 0; border-top: 1px solid var(--line); margin: 0; }
    .choices { display: flex; gap: 12px; flex-wrap: wrap; }
    .choice { position: relative; flex: 1; min-width: 80px; }
    .choice input { position: absolute; opacity: 0; width: 1px; height: 1px; }
    .choice label { display: flex; align-items: center; justify-content: center; gap: 8px; min-height: 48px; padding: 12px; border: 1px solid var(--input-line); border-radius: 8px; font-size: 14px; font-weight: 400; cursor: pointer; margin: 0; transition: background var(--ease), border-color var(--ease); }
    .choice input:checked + label { background: var(--sage); border-color: var(--green); color: var(--green); box-shadow: inset 0 0 0 1px var(--green); }
    .choice input:checked + label::after { content: '✓'; font-size: 14px; }
    .choice input:focus-visible + label { outline: 3px solid var(--focus); outline-offset: 3px; }
    textarea { min-height: 88px; height: 88px; resize: vertical; }
    .schedule-grid { display: grid; grid-template-columns: 1.15fr 1fr; gap: 28px; }
    .calendar { min-width: 0; }
    .calendar-header { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 12px; }
    .calendar-header h3 { font-size: 14px; margin: 0; font-weight: 500; }
    .calendar-nav { display: flex; gap: 0; }
    .icon-button { display: grid; place-items: center; width: 44px; height: 44px; border: 0; border-radius: 6px; background: transparent; }
    .icon-button:disabled { color: #b8c0b4; }
    .calendar-week, .calendar-days { display: grid; grid-template-columns: repeat(7, 1fr); gap: 4px; text-align: center; }
    .calendar-week span { padding: 4px 0 8px; font-size: 11px; color: var(--muted); }
    .day { border: 1px solid transparent; height: 40px; min-width: 0; background: none; border-radius: 8px; font-size: 13px; font-variant-numeric: tabular-nums; }
    .day:disabled { color: #b5bcb1; }
    .day.today { text-decoration: underline; text-underline-offset: 4px; }
    .day[aria-pressed='true'] { background: var(--green); color: white; }
    .slot-heading { font-size: 13px; font-weight: 500; margin: 12px 0; }
    .time-choices { display: grid; gap: 8px; }
    .time-choices .choice label { min-height: 44px; font-size: 12px; }
    .choice input:disabled + label { opacity: .45; cursor: default; text-decoration: line-through; }
    .selection-note { border-top: 1px solid var(--line); margin-top: 24px; padding-top: 16px; display: flex; align-items: flex-start; gap: 8px; font-size: 12px; color: var(--muted); }
    .selection-note .icon { width: 16px; height: 16px; margin-top: 1px; }
    .selection-note p { margin: 0; }
    .review-group { padding: 20px 0; border-bottom: 1px solid var(--line); }
    .review-group:first-child { padding-top: 0; }
    .review-group:last-child { border: 0; padding-bottom: 0; }
    .review-group-heading { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-bottom: 8px; }
    .review-group h3 { font-size: 13px; font-weight: 500; margin: 0; color: var(--muted); display: flex; align-items: center; gap: 8px; }
    .review-group h3 .icon { width: 16px; height: 16px; }
    .edit-button { padding: 8px 0 8px 12px; min-width: 44px; min-height: 44px; border: 0; background: none; font-size: 12px; color: var(--green); text-decoration: underline; text-underline-offset: 3px; }
    .review-value { margin: 0; font-size: 14px; overflow-wrap: anywhere; }
    .review-sub { color: var(--muted); font-size: 13px; margin: 4px 0 0; white-space: pre-line; overflow-wrap: anywhere; }
    .demo-note { padding: 16px; background: var(--sage); border-radius: 8px; margin-top: 24px; font-size: 12px; color: var(--green); display: flex; gap: 8px; align-items: flex-start; }
    .demo-note .icon { width: 16px; height: 16px; margin-top: 1px; }
    .demo-note p { margin: 0; }
    .success-heading { text-align: center; padding-bottom: 28px; margin-bottom: 24px; border-bottom: 1px solid var(--line); }
    .success-mark { width: 64px; height: 64px; display: grid; place-items: center; margin: 0 auto 20px; background: var(--sage); border-radius: 50%; color: var(--green); }
    .success-mark .icon { width: 28px; height: 28px; }
    .success-heading h2 { margin-bottom: 12px; }
    .success-heading p { color: var(--muted); font-size: 14px; max-width: 400px; margin: auto; }
    .success-footer { justify-content: center; }
    .panel.enter { animation: arrive 200ms ease-out; }
    @keyframes arrive { from { opacity: .4; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }
    @media (hover: hover) {
      .primary:hover { background: var(--green-hover); }
      .secondary:hover, .edit-button:hover { color: var(--ink); }
      .icon-button:not(:disabled):hover, .counter button:not(:disabled):hover { background: var(--sage); }
      .day:not(:disabled):not([aria-pressed='true']):hover { background: var(--sage); }
      .choice input:not(:disabled) + label:hover { border-color: var(--green); background: #f4f7f0; }
      .step-button:not(:disabled):hover .step-name { text-decoration: underline; text-underline-offset: 4px; }
    }
    @media (max-width: 600px) {
      .site-header { height: 80px; padding: 0 24px; }
      .wordmark { font-size: 28px; }
      .brand-mark { width: 27px; height: 30px; }
      .header-note { font-size: 12px; }
      main { padding: 24px 16px 32px; }
      .intro { margin-bottom: 32px; }
      h1 { font-size: 36px; letter-spacing: -1.2px; margin-bottom: 12px; }
      .intro p { font-size: 14px; max-width: 280px; margin: auto; }
      .progress { margin: 0 -4px 24px; }
      .step-button { min-width: 0; padding: 0 4px; gap: 10px; }
      .step-name { font-size: 11px; }
      .step-number { width: 36px; height: 36px; font-size: 12px; }
      .progress li:not(:last-child)::after { top: 18px; left: calc(50% + 24px); right: calc(-50% + 24px); }
      .card-content { padding: 24px; }
      .section-icon { margin-bottom: 16px; width: 40px; height: 40px; }
      .section-top { margin-bottom: 24px; gap: 8px; }
      h2 { font-size: 24px; }
      .description { font-size: 13px; }
      .step-count { font-size: 11px; margin-top: 5px; }
      .fields { gap: 20px 12px; }
      input:not([type='radio']), textarea { font-size: 16px; padding: 12px; }
      .card-footer { padding: 20px 24px; }
      .primary { padding: 12px 20px; }
      .next-note { max-width: 110px; }
      .next-note strong { display: block; }
      .schedule-grid { grid-template-columns: 1fr; gap: 24px; }
      .day { min-height: 44px; }
      .time-choices { grid-template-columns: 1fr 1fr; }
      .slot-heading { margin-top: 0; }
      .time-choices .choice label { padding: 12px 8px; }
      .booking-card { border-radius: 16px; }
      .counter-label { gap: 8px; }
    }
    @media (max-width: 370px) {
      .fields { grid-template-columns: 1fr; }
      .fields .field { grid-column: 1 / -1; }
      .header-note .icon { display: none; }
      .card-content, .card-footer { padding: 24px 20px; }
      .primary { padding: 12px 16px; }
      .step-count { display: none; }
      .counter-label { gap: 4px; }
      .counter-label .icon { display: none; }
    }
    @media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } *, *::before, *::after { animation: none "'!important; transition: none !important; } }
  </style>
</head>
<body>
  <svg xmlns="http://www.w3.org/2000/svg" style="display:none" aria-hidden="true">
    <symbol id="i-user" viewBox="0 0 24 24"><circle cx="12" cy="8" r="3.5"/><path d="M5 21v-2a7 7 0 0 1 14 0v2"/></symbol>
    <symbol id="i-home" viewBox="0 0 24 24"><path d="m3 10 9-7 9 7M5 9v11h14V9M9 20v-7h6v7"/></symbol>
    <symbol id="i-calendar" viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h1m6 0h1m-8 3h1"/></symbol>
    <symbol id="i-review" viewBox="0 0 24 24"><path d="M9 4H6a2 2 0 0 0-2 2v14h16V6a2 2 0 0 0-2-2h-3"/><rect x="9" y="2" width="6" height="5" rx="1"/><path d="m8 14 3 3 5-6"/></symbol>
    <symbol id="i-arrow" viewBox="0 0 24 24"><path d="M4 12h15m-6-6 6 6-6 6"/></symbol>
    <symbol id="i-back" viewBox="0 0 24 24"><path d="M20 12H5m6-6-6 6 6 6"/></symbol>
    <symbol id="i-check" viewBox="0 0 24 24"><path d="m5 12 4 4L19 6"/></symbol>
    <symbol id="i-clock" viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></symbol>
    <symbol id="i-plus" viewBox="0 0 24 24"><path d="M5 12h14M12 5v14"/></symbol>
    <symbol id="i-minus" viewBox="0 0 24 24"><path d="M5 12h14"/></symbol>
    <symbol id="i-bed" viewBox="0 0 24 24"><path d="M3 19v-7h18v7M5 12V5h14v7M3 17h18M7 12V9h4v3m2 0V9h4v3"/></symbol>
    <symbol id="i-bath" viewBox="0 0 24 24"><path d="M3 12h18v2a6 6 0 0 1-6 6H9a6 6 0 0 1-6-6v-2Zm2 0V5a3 3 0 0 1 6 0M8 20v2m8-2v2M9 6h4"/></symbol>
    <symbol id="i-info" viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/></symbol>
    <symbol id="i-left" viewBox="0 0 24 24"><path d="m14 6-6 6 6 6"/></symbol>
    <symbol id="i-right" viewBox="0 0 24 24"><path d="m10 6 6 6-6 6"/></symbol>
    <symbol id="i-sparkle" viewBox="0 0 24 24"><path d="M12 3c0 6-3 9-9 9 6 0 9 3 9 9 0-6 3-9 9-9-6 0-9-3-9-9Z"/></symbol>
  </svg>
  <header class="site-header">
    <div class="wordmark" aria-label="neat home cleaning">
      <svg class="brand-mark" viewBox="0 0 34 38" fill="none" aria-hidden="true"><path d="M3 18 17 5l14 13v15H3V18Z" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/><path d="M17 13c0 6-2 8-7 8 5 0 7 2 7 7 0-5 2-7 7-7-5 0-7-2-7-8Z" fill="currentColor"/><path d="M25 3v6m-3-3h6" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>
      neat<span style="color:var(--green);margin-left:-8px">.</span>
    </div>
    <span class="header-note"><svg class="icon"><use href="#i-home"/></svg> Home cleaning</span>
  </header>
  <main>
    <div class="intro">
      <h1>Let’s book your clean.</h1>
      <p>A few details. A time that suits you. A fresher home.</p>
    </div>
    <nav aria-label="Booking progress">
      <ol class="progress" id="progress">
        <li class="current"><button class="step-button" type="button" data-step="0" aria-current="step"><span class="step-number">1</span><span class="step-name">Contact details</span></button></li>
        <li><button class="step-button" type="button" data-step="1" disabled><span class="step-number">2</span><span class="step-name">Home details</span></button></li>
        <li><button class="step-button" type="button" data-step="2" disabled><span class="step-number">3</span><span class="step-name">Date & time</span></button></li>
        <li><button class="step-button" type="button" data-step="3" disabled><span class="step-number">4</span><span class="step-name">Review</span></button></li>
      </ol>
    </nav>
    <div class="booking-card" id="booking-card">
      <form id="booking-form" novalidate>
        <section class="panel" data-panel="0" aria-labelledby="contact-heading">
          <div class="card-content">
            <div class="section-icon"><svg class="icon" aria-hidden="true"><use href="#i-user"/></svg></div>
            <div class="section-top"><div><h2 id="contact-heading" tabindex="-1">First, a little about you.</h2><p class="description">How can we reach you about your clean?</p></div><span class="step-count">Step 1 of 4</span></div>
            <div class="fields">
              <div class="field"><label for="first-name">First name</label><input id="first-name" name="firstName" autocomplete="given-name" placeholder="e.g. Alex" maxlength="80" required aria-describedby="first-name-error"><p class="field-error" id="first-name-error" aria-live="polite"></p></div>
              <div class="field"><label for="last-name">Last name</label><input id="last-name" name="lastName" autocomplete="family-name" placeholder="e.g. Morgan" maxlength="80" required aria-describedby="last-name-error"><p class="field-error" id="last-name-error" aria-live="polite"></p></div>
              <div class="field full"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" inputmode="email" placeholder="you@example.com" maxlength="254" required aria-describedby="email-error"><p class="field-error" id="email-error" aria-live="polite"></p></div>
              <div class="field full"><label for="phone">Phone number</label><input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="Your phone number" maxlength="30" required aria-describedby="phone-error"><p class="field-error" id="phone-error" aria-live="polite"></p></div>
            </div>
            <p class="hint">All fields are required.</p>
          </div>
        </section>
        <section class="panel" data-panel="1" aria-labelledby="home-heading" hidden>
          <div class="card-content">
            <div class="section-icon"><svg class="icon" aria-hidden="true"><use href="#i-home"/></svg></div>
            <div class="section-top"><div><h2 id="home-heading" tabindex="-1">Tell us about your home.</h2><p class="description">A little context for your clean.</p></div><span class="step-count">Step 2 of 4</span></div>
            <div class="home-fields">
              <div class="field"><label for="address">Street address</label><input id="address" name="address" autocomplete="address-line1" placeholder="Street and house number" maxlength="200" required aria-describedby="address-error"><p class="field-error" id="address-error" aria-live="polite"></p></div>
              <div class="fields">
                <div class="field"><label for="unit">Apartment / unit <span class="optional">(optional)</span></label><input id="unit" name="unit" autocomplete="address-line2" placeholder="e.g. Apt 4B" maxlength="80"></div>
                <div class="field"><label for="postcode">ZIP / postal code</label><input id="postcode" name="postcode" autocomplete="postal-code" placeholder="Your postal code" maxlength="16" required aria-describedby="postcode-error"><p class="field-error" id="postcode-error" aria-live="polite"></p></div>
              </div>
