    .choice input { position: absolute; opacity: 0; width: 1px; height: 1px; }
    .choice label { display: flex; align-items: center; justify-content: center; gap: 8px; min-height: 48px; padding: 12px; border: 1px solid var(--input-line); border-radius: 8px; font-size: 14px; font-weight: 400; cursor: pointer; margin: 0; transition: background var(--ease), border-color var(--ease); }
    .choice input:checked + label { background: var(--sage); border-color: var(--green); color: var(--green); box-shadow: inset 0 0 0 1px var(--green); }
    .choice input:checked + label::after { content: '✓'; font-size: 14px; }
    .choice input:focus-visible + label { outline: 3px solid var(--focus); outline-offset: 3px; }
    textarea { min-height: 88px; height: 88px; resize: vertical; }
    .schedule-grid { display: grid; grid-template-columns: 1.15fr 1fr; gap: 28px; }
    .calendar { min-width: 0; }
