    .success-mark .icon { width: 28px; height: 28px; }
    .success-heading h2 { margin-bottom: 12px; }
    .success-heading p { color: var(--muted); font-size: 14px; max-width: 400px; margin: auto; }
    .success-footer { justify-content: center; }
    .panel.enter { animation: arrive 200ms ease-out; }
    @keyframes arrive { from { opacity: .4; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }
    @media (hover: hover) {
